import React from "react";
import { loadFont } from "@remotion/google-fonts/Montserrat";
import {
  AbsoluteFill,
  Easing,
  Img,
  OffthreadVideo,
  Sequence,
  interpolate,
  staticFile,
  useCurrentFrame,
} from "remotion";

// PASTOR ALEX · Bispo Alex Neves, Igreja Despertar da Fé (Sertãozinho). Formato de tráfego 9:16 a partir do vídeo dele
// falando (video-1, 480x368, 56,8 s). A fala é a narração, sem cortes (tempo da composição = tempo do vídeo original).
// Pouco material → jeito motion: a filmagem dele em cartão alterna com cenas desenhadas na identidade do logo
// (azul-marinho, azul-céu do globo, chama cobre/vinho, branco da pomba). Problema em cenas escuras; a partir da oração,
// cenas claras. Transições nunca iguais duas vezes seguidas.

const { fontFamily: MS } = loadFont("normal", { weights: ["700", "800", "900"], subsets: ["latin", "latin-ext"] });

export const PA_FPS = 30;
export const PA_FRAMES = Math.round(59.4 * PA_FPS);

const NAVY = "#121747";
const NAVY2 = "#1C2363";
const INDIGO = "#3D4499";
const SKY = "#00AEEF";
const FLAME = "#D9814A";
const WINE = "#8B2A2E";
const LIGHT = "#F7F7F7";
const WHITE = "#FFFFFF";

const cl = { extrapolateLeft: "clamp", extrapolateRight: "clamp" } as const;
const OUT = Easing.bezier(0.16, 1, 0.3, 1);
const BACK = Easing.bezier(0.34, 1.56, 0.64, 1);
const k = (t: number, a: number, d = 0.4) => interpolate(t, [a, a + d], [0, 1], { ...cl, easing: OUT });
const pop = (t: number, a: number, d = 0.4) => interpolate(t, [a, a + d], [0, 1], { ...cl, easing: BACK });
const lin = (t: number, a: number, b: number) => interpolate(t, [a, b], [0, 1], cl);
const f = (s: number) => Math.round(s * PA_FPS);

// ---------- texto: entra com batida, fica parado, some inteiro antes do próximo ----------
export const Say: React.FC<{
  t: number;
  at: number;
  until?: number;
  children: React.ReactNode;
  size?: number;
  color?: string;
  top: number;
  weight?: number;
}> = ({ t, at, until = 999, children, size = 92, color = WHITE, top, weight = 900 }) => {
  if (t < at || t > until) return null;
  const e = k(t, at, 0.26);
  const out = until < 999 ? interpolate(t, [until - 0.12, until], [1, 0], cl) : 1;
  return (
    <div
      style={{
        position: "absolute",
        left: 120,
        right: 120,
        top,
        display: "flex",
        flexDirection: "column",
        alignItems: "center",
        textAlign: "center",
        fontFamily: MS,
        fontWeight: weight,
        fontSize: size,
        lineHeight: 1.04,
        color,
        textTransform: "uppercase",
        letterSpacing: "-0.01em",
        opacity: Math.min(1, e * 2.5) * out,
        transform: `scale(${(1.28 - 0.28 * e).toFixed(4)})`,
        filter: `blur(${((1 - e) * 10).toFixed(1)}px)`,
      }}
    >
      <div>{children}</div>
    </div>
  );
};
export const Hi: React.FC<{ c?: string; children: React.ReactNode }> = ({ c = SKY, children }) => <span style={{ color: c }}>{children}</span>;
