// ---------- transições de entrada ----------
type Tin = "none" | "iris" | "blur" | "push" | "wipe" | "card" | "flash";
const TD = 0.36;
const tinStyle = (type: Tin, p: number): React.CSSProperties => {
  const e = Easing.bezier(0.33, 0, 0.2, 1)(Math.min(1, Math.max(0, p)));
  if (type === "iris") return { clipPath: `circle(${(e * 118).toFixed(2)}% at 50% 46%)` };
  if (type === "blur" || type === "flash")
    return { opacity: e, filter: `blur(${((1 - e) * 26).toFixed(1)}px)`, transform: `scale(${(1.14 - 0.14 * e).toFixed(4)})` };
  if (type === "push") return { transform: `translateY(${((1 - e) * 1920).toFixed(0)}px)`, boxShadow: "0 -30px 80px rgba(0,0,0,0.5)" };
  if (type === "wipe") {
    const x = -40 + e * 180;
    return { clipPath: `polygon(0% 0%, ${x.toFixed(1)}% 0%, ${(x - 40).toFixed(1)}% 100%, 0% 100%)` };
  }
  if (type === "card")
    return {
      opacity: Math.min(1, e * 2.5),
      transform: `translateY(${((1 - e) * 260).toFixed(0)}px) scale(${(0.72 + 0.28 * e).toFixed(4)})`,
      borderRadius: (1 - e) * 70,
      overflow: "hidden",
    };
  return {};
};

// cena: aparece de (a - TD/2) até (b + TD/2), com transição de entrada e câmera em movimento
export const Scene: React.FC<{
  t: number;
  a: number;
  b: number;
  tin: Tin;
  bg: string;
  zoom?: [number, number];
  drift?: number;
  children: React.ReactNode;
}> = ({ t, a, b, tin, bg, zoom = [1, 1.06], drift = 0, children }) => {
  const s0 = tin === "none" ? a : a - TD / 2;
  if (t < s0 || t > b + TD / 2) return null;
  const p = tin === "none" ? 1 : lin(t, s0, s0 + TD);
  const c = lin(t, a, b);
  const z = zoom[0] + (zoom[1] - zoom[0]) * c;
  const flash = tin === "flash" ? interpolate(t, [s0, s0 + TD * 0.6, s0 + TD * 1.6], [0, 0.85, 0], cl) : 0;
  return (
    <AbsoluteFill style={{ ...tinStyle(tin, p) }}>
      <AbsoluteFill style={{ background: bg, overflow: "hidden" }}>
        <AbsoluteFill style={{ transform: `scale(${z.toFixed(4)}) translateY(${(drift * c).toFixed(1)}px)` }}>{children}</AbsoluteFill>
      </AbsoluteFill>
      {flash > 0 && <AbsoluteFill style={{ background: WHITE, opacity: flash }} />}
    </AbsoluteFill>
  );
};

