// selo redondo com ícone (entra com impulso)
const Seal: React.FC<{ t: number; at: number; name: string; size?: number; bg?: string; ring?: string; ink?: string }> = ({ t, at, name, size = 120, bg = INDIGO, ring = SKY, ink = WHITE }) => {
