// lettering do padrão: selo (opcional), linha pequena espaçada e palavra grande em tarja; tudo entra e fica parado
const Letter: React.FC<{
  t: number; at: number; until?: number; top: number; small?: string; big: string; icon?: string; big2?: string;
  tag?: string; ink?: string; size?: number; smallColor?: string;
}> = ({ t, at, until = 999, top, small, big, icon, big2, tag = INDIGO, ink = WHITE, size = 96, smallColor = WHITE }) => {
  if (t < at || t > until) return null;
  const out = until < 999 ? interpolate(t, [until - 0.12, until], [1, 0], cl) : 1;
  const e1 = k(t, at + 0.05, 0.35);
  const e2 = k(t, at + (small ? 0.18 : 0.05), 0.3);
  const e3 = k(t, at + 0.32, 0.3);
  const shadow = "0 4px 18px rgba(0,0,0,0.55)";
  return (
    <div style={{ position: "absolute", left: 100, right: 100, top, display: "flex", flexDirection: "column", alignItems: "center", gap: 14, opacity: out, fontFamily: MS, textTransform: "uppercase" }}>
      {icon && <Seal t={t} at={at} name={icon} size={118} />}
      {small && (
        <div style={{ fontWeight: 800, fontSize: 34, letterSpacing: "0.16em", color: smallColor, textShadow: shadow, opacity: e1, transform: `translateY(${((1 - e1) * 24).toFixed(1)}px)`, textAlign: "center" }}>{small}</div>
      )}
      <div style={{ background: tag, color: ink, fontWeight: 900, fontSize: size, lineHeight: 1.02, padding: "10px 30px 6px", borderRadius: 10, boxShadow: "0 10px 30px rgba(0,0,0,0.35)", textAlign: "center", opacity: Math.min(1, e2 * 2), transform: `scale(${(1.25 - 0.25 * e2).toFixed(4)})`, filter: `blur(${((1 - e2) * 8).toFixed(1)}px)` }}>{big}</div>
      {big2 && (
        <div style={{ background: WHITE, color: NAVY, fontWeight: 900, fontSize: size * 0.8, lineHeight: 1.02, padding: "8px 26px 4px", borderRadius: 10, boxShadow: "0 10px 30px rgba(0,0,0,0.35)", opacity: Math.min(1, e3 * 2), transform: `scale(${(1.25 - 0.25 * e3).toFixed(4)})` }}>{big2}</div>
      )}
    </div>
  );
};

// botão do padrão: "queremos orar por você / clica aqui agora", pulsando de leve
const Cta: React.FC<{ t: number; a: number; b: number; top: number }> = ({ t, a, b, top }) => {
  if (t < a || t > b) return null;
  const e = pop(t, a, 0.5);
  const out = interpolate(t, [b - 0.15, b], [1, 0], cl);
  const pulse = 1 + 0.035 * Math.max(0, Math.sin((t - a) * Math.PI * 2 * 0.9));
  return (
    <div style={{ position: "absolute", left: 0, right: 0, top, display: "flex", justifyContent: "center", opacity: Math.min(1, e * 3) * out }}>
      <div style={{ transform: `scale(${((0.6 + 0.4 * e) * pulse).toFixed(4)})`, background: SKY, border: `4px solid ${WHITE}`, borderRadius: 999, padding: "12px 46px 12px 50px", display: "flex", alignItems: "center", gap: 18, boxShadow: "0 14px 40px rgba(0,174,239,0.45)", fontFamily: MS, color: NAVY, textTransform: "uppercase" }}>
